//! Agents: the forms, saving, and deleting. Generated by `cargo offrails generate resource agents name:string description:text`.

use axum::http::StatusCode;
use board::models::agent;
use board::routes::paths;

use super::submit;
use crate::factories;
use crate::support::TestApp;

#[tokio::test]
async fn new_renders_the_form() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    app.get(&paths::new_agent())
        .await
        .assert_ok()
        .assert_contains(&format!("action=\"{}\"", paths::agents()));
}

#[tokio::test]
async fn create_saves_and_redirects_to_the_agent() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let params = factories::agent_params(app.db(), &me).await;
    let res = submit(&app, &paths::agents(), &params).await;
    let (rows, _) = agent::all_for(app.db(), &me, board::models::Page::default())
        .await
        .unwrap();
    assert_eq!(rows.len(), 1, "one agent saved");
    res.assert_redirect_to(&paths::agent(rows[0].id));
    app.get(&paths::agent(rows[0].id))
        .await
        .assert_ok()
        .assert_text("Agent was successfully created.");
}

#[tokio::test]
async fn create_with_invalid_params_is_422_with_the_errors_and_the_input() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let mut params = factories::agent_params(app.db(), &me).await;
    params.name = "".into();
    let res = submit(&app, &paths::agents(), &params).await;
    res.assert_status(StatusCode::UNPROCESSABLE_ENTITY)
        .assert_text("Name can't be blank");
    let (rows, _) = agent::all_for(app.db(), &me, board::models::Page::default())
        .await
        .unwrap();
    assert!(rows.is_empty(), "nothing saved");
}

#[tokio::test]
async fn edit_shows_the_saved_values_and_update_saves_changes() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::agent(app.db(), &me).await;
    app.get(&paths::edit_agent(record.id))
        .await
        .assert_ok()
        .assert_contains(&format!("action=\"{}\"", paths::agent(record.id)));
    let mut params = agent::AgentParams::from(&record);
    params.name = "Changed by the test".into();
    submit(&app, &paths::agent(record.id), &params)
        .await
        .assert_redirect_to(&paths::agent(record.id));
    app.get(&paths::agent(record.id))
        .await
        .assert_ok()
        .assert_text("Agent was successfully updated.")
        .assert_text("Changed by the test");
}

#[tokio::test]
async fn update_with_invalid_params_is_422_and_changes_nothing() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::agent(app.db(), &me).await;
    let mut params = agent::AgentParams::from(&record);
    params.name = "".into();
    submit(&app, &paths::agent(record.id), &params)
        .await
        .assert_status(StatusCode::UNPROCESSABLE_ENTITY)
        .assert_text("Name can't be blank");
    assert_eq!(
        factories::reload_agent(app.db(), record.id).await,
        Some(record)
    );
}

#[tokio::test]
async fn destroy_deletes_and_redirects_to_the_list() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let record = factories::agent(app.db(), &me).await;
    app.post_form(&paths::delete_agent(record.id), &[])
        .await
        .assert_redirect_to(&paths::agents());
    assert!(factories::reload_agent(app.db(), record.id).await.is_none());
    app.get(&paths::agent(record.id))
        .await
        .assert_status(StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn markup_in_a_agent_is_shown_as_text() {
    let app = TestApp::new().await;
    let me = factories::user(app.db(), "me@example.com").await;
    app.sign_in_as(&me).await;
    let mut params = factories::agent_params(app.db(), &me).await;
    params.name = "<script>alert(1)</script>".into();
    let record = factories::agent_with(app.db(), &me, params).await;
    for path in [paths::agents(), paths::agent(record.id)] {
        app.get(&path)
            .await
            .assert_ok()
            .assert_not_contains("<script>alert(1)")
            .assert_text("<script>alert(1)</script>");
    }
}
